// int's members: one function per member, each declared by the //kavun:member directive in its doc comment. The table,
// intMethods, and the member entries of docs/reference/types/int.md (alphabetical, so the order here is free) are
// generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Report truthiness, which is inequality with zero: `!!x` ⟺ `x != 0`.
//
// Truthiness is inequality with the type's zero, in both spellings — the member and the free builtin:
//
// ```go
// (0).is_true()    // => false
// (7).is_true()    // => true
// is_true(0)       // => false
// is_true(-3)      // => true
// !!0              // => false
// ```
//
//kavun:member is_true pure () -> bool
func intIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// `format([spec])` renders the value; with no spec it is the plain decimal rendering. Verbs: `d` (decimal,
// default), `b` / `o` / `x` / `X` (binary / octal / hex, prefixed `0b` / `0o` / `0x`), `c` (the code point as a
// character), `q` (the code point as a quoted character literal). Grouping (`,` for decimal, `_` for the other
// bases), sign, and zero-padding compose with them:
//
// ```go
// (255).format("x")          // => "0xff"
// (255).format("X")          // => "0xFF"
// (255).format("b")          // => "0b11111111"
// (255).format("o")          // => "0o377"
// (1234567).format(",d")     // => "1,234,567"
// (42).format("+d")          // => "+42"
// (42).format("08d")         // => "00000042"
// (65).format("c")           // => "A"
// (10).format("q")           // => "'\\n'"
// ```
//
//kavun:member format pure ([spec]) -> string
func intFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Answer the receiver — an `int` is always immutable.
//
// Identity no-ops — an `int` is always immutable — kept so generic code can `x.copy()` any value without a type
// error:
//
// ```go
// (5).copy()      // => 5
// (5).freeze()    // => 5
// ```
//
//kavun:member copy pure () -> int
func intCopy(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver — an `int` is always immutable; see [`copy`](#copy).
//
//kavun:member freeze pure () -> int
func intFreeze(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver, the identity conversion.
//
//kavun:member int pure ([default]) -> int
func intInt(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), intTypeName, args, true, v)
}

// Convert to the nearest `float`, exact up to 2⁵³ and silently approximate above.
//
// ```go
// (65).float()        // => 65.0
// ```
//
//kavun:member float pure ([default]) -> float
func intFloat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	f, ok := v.AsFloat()
	return ConvMember(id.String(), intTypeName, args, ok, FloatValue(f))
}

// Convert to a `decimal`, exactly.
//
// ```go
// (65).decimal()      // => 65d
// ```
//
//kavun:member decimal pure ([default]) -> decimal
func intDecimal(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	d, ok := v.AsDecimal()
	return ConvMember(id.String(), intTypeName, args, ok, NewDecimalValue(d))
}

// Answer `false` for zero and `true` otherwise.
//
// ```go
// (2).bool()          // => true
// ```
//
//kavun:member bool pure ([default]) -> bool
func intBool(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	b, ok := v.AsBool()
	return ConvMember(id.String(), intTypeName, args, ok, BoolValue(b))
}

// Convert to a `rune`; a value that is not a Unicode code point (0–0x10FFFF, surrogates excluded) raises unless a
// default is given.
//
// ```go
// (65).rune()         // => 'A'
// (55296).rune()      // Error: conversion: cannot convert int to rune — a surrogate is not a code point
// (55296).rune('?')   // => '?'
// (1114112).rune()    // Error: conversion: cannot convert int to rune — past 0x10FFFF
// ```
//
//kavun:member rune pure ([default]) -> rune
func intRune(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	c, ok := v.AsRune()
	return ConvMember(id.String(), intTypeName, args, ok, RuneValue(c))
}

// Convert to a `byte`; a value outside 0–255 raises unless a default is given.
//
// ```go
// (65).byte()         // => byte(65)
// (300).byte()        // Error: conversion: cannot convert int to byte
// (300).byte(b'0')    // => byte(48) — the default answers instead
// ```
//
//kavun:member byte pure ([default]) -> byte
func intByte(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	b, ok := v.AsByte()
	return ConvMember(id.String(), intTypeName, args, ok, ByteValue(b))
}

// Render the value as its decimal text, a `string`.
//
// ```go
// (65).string()       // => "65"
// ```
//
//kavun:member string pure ([default]) -> string
func intString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	// total — the default slot never fires, but every conversion carries it
	s, _ := v.AsString()
	return ConvMember(id.String(), intTypeName, args, true, NewStringValue(s))
}

// Render the value as its decimal text, as `runes`; see [`string`](#string).
//
// ```go
// (65).runes()        // => u"65"
// ```
//
//kavun:member runes pure ([default]) -> runes
func intRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	s, ok := v.AsString()
	return ConvMember(id.String(), intTypeName, args, ok, NewRunesValue(text.DecodeText(s), false))
}

// Read the value as a unix timestamp in seconds.
//
// In conversion context an int is a **unix timestamp** (the duration reading belongs to operator context — `t + n` adds
// nanoseconds; see [time](time.md) — and to the [Durations](#durations) members). Each member names the
// encoding it reads and inverts the `time` accessor with the matching suffix (`time_ms` ↔ `unix_ms`, and the unsuffixed
// `time()` ↔ `unix()` / `int()`). All produce UTC:
//
// ```go
// (0).time()                              // => time("1970-01-01T00:00:00Z")
// (1704067200).time()                     // => time("2024-01-01T00:00:00Z")
// (1704067200123).time_ms()               // => time("2024-01-01T00:00:00.123Z")
// (1704067200123456).time_micro()         // => time("2024-01-01T00:00:00.123456Z")
// (1704067200123456789).time_nano()       // => time("2024-01-01T00:00:00.123456789Z")
// ```
//
//kavun:member time pure ([default]) -> time
func intTime(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	t, _ := v.AsTime()
	return ConvMember(id.String(), intTypeName, args, true, NewTimeValue(t))
}

// Read the value as a day count since 1970-01-01, the inverse of `d.int()`.
//
//kavun:member date pure ([default]) -> date
func intDate(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	// in conversion context an int is a day count since 1970-01-01 — the inverse of d.int(); in operator
	// context (d + n) it is a number of days
	dd, ok := intTypeAsDate(v)
	return ConvMember(id.String(), intTypeName, args, ok, DateValue(dd))
}

// Read the value as a unix timestamp in milliseconds; see [`time`](#time).
//
//kavun:member time_ms pure ([default]) -> time
func intTimeMs(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), intTypeName, args, true, NewTimeValue(time.UnixMilli(int64(v.Data)).UTC()))
}

// Read the value as a unix timestamp in microseconds; see [`time`](#time).
//
//kavun:member time_micro pure ([default]) -> time
func intTimeMicro(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), intTypeName, args, true, NewTimeValue(time.UnixMicro(int64(v.Data)).UTC()))
}

// Read the value as a unix timestamp in nanoseconds; see [`time`](#time).
//
//kavun:member time_nano pure ([default]) -> time
func intTimeNano(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), intTypeName, args, true, NewTimeValue(time.Unix(0, int64(v.Data)).UTC()))
}

// Report whether the value is NaN — always `false` on an `int`.
//
// Constant `false` — an `int` can never be NaN. It exists so generic numeric code can ask the question of any
// number:
//
// ```go
// (5).is_nan()    // => false — always
// ```
//
//kavun:member is_nan pure () -> bool
func intIsNaN(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return False, nil
}

// Report whether the value is infinite — always `false` on an `int`; see [`is_nan`](#is_nan).
//
// ```go
// (5).is_inf()    // => false — always
// ```
//
//kavun:member is_inf pure () -> bool
func intIsInf(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return False, nil
}

// Answer the sign as an `int`: `-1`, `0` or `1`.
//
// ```go
// (-5).sign()     // => -1
// (0).sign()      // => 0
// (5).sign()      // => 1
// ```
//
//kavun:member sign pure () -> int
func intSign(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	if v.Data == 0 {
		return IntValue(0), nil
	} else if int64(v.Data) > 0 {
		return IntValue(1), nil
	} else {
		return IntValue(-1), nil
	}
}

// Answer the absolute value.
//
// ```go
// (-5).abs()      // => 5
// (5).abs()       // => 5
// ```
//
// `math.min_int.abs()` raises `int overflow`: the true absolute value does not fit in 64 bits.
//
//kavun:member abs pure () -> int
func intAbs(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	i := int64(v.Data)
	if i == math.MinInt64 {
		// |MinInt64| does not fit — int is checked, it never wraps
		return Undefined, errs.NewInvalidValueError("int overflow")
	}
	if i < 0 {
		return IntValue(-i), nil
	}
	return v, nil
}

// --- durations (helpers in tools.go): build in a unit, read in a unit, render

// Answer this many nanoseconds as an `int` duration in nanoseconds; see [Durations](#durations).
//
// The `default` is taken for interface uniformity (`"1h".nanoseconds([default])` parses) and is never used.
//
//kavun:member nanoseconds pure ([default]) -> int
func intNanoseconds(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	// total — n nanoseconds is n; the default slot never fires, but this conversion carries it as text's does
	return ConvMember(id.String(), intTypeName, args, true, IntValue(int64(v.Data)))
}

// Answer this many microseconds as an `int` duration in nanoseconds; see [Durations](#durations).
//
//kavun:member microseconds pure () -> int
func intMicroseconds(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return durationFromInt(id, int64(v.Data), time.Microsecond)
}

